actions.script:
const L = (text) => ec.l10n.localize(text)
const num = (value) => value == null ? null : (typeof value === 'object' && value.toNumber ? value.toNumber() : Number(value))
const sizeOf = (value) => {
    const size = num(value)
    if (size == null || Number.isNaN(size)) return ''
    if (size < 1024) return size + ' B'
    if (size < 1048576) return (size / 1024).toFixed(1) + ' KB'
    if (size < 1073741824) return (size / 1048576).toFixed(1) + ' MB'
    return (size / 1073741824).toFixed(1) + ' GB'
}
const when = (millis) => millis == null || Number.isNaN(num(millis)) ? '' : ec.l10n.format(new Date(num(millis)), 'yyyy-MM-dd HH:mm')
const rail = ec.service.sync().name('ironstone.commons.DriveServices.get#FilesData').call()
driveId = drive || rail.personalDriveId || null
folderPath = path || ''
driveList = Array.from(rail.driveList || []).map((item) => ({driveId: item.driveId, shownName: item.driveName || item.driveId,
    kindText: item.isRecords ? L('Records') : item.isMirror ? L('Mirror') : item.driveKindEnumId === 'RdkPersonal' ? L('Personal') : L('Shared'),
    openText: item.driveId === driveId ? L('Open') : ''}))
fileList = []
breadcrumbList = []
folderTitle = ''
hiddenCount = 0
if (driveId && !ec.message.hasError()) {
    const out = ec.service.sync().name('ironstone.commons.DriveServices.list#FolderView').parameters({driveId: driveId, path: folderPath}).call()
    if (!ec.message.hasError()) {
        folderTitle = out.record?.title || out.folder?.name || ''
        hiddenCount = out.hiddenCount || 0
        breadcrumbList = Array.from(out.breadcrumbList || []).filter((crumb) => crumb.path != null && !crumb.view)
                .map((crumb) => ({name: crumb.name || crumb.path, crumbPath: crumb.path}))
        fileList = Array.from(out.fileList || []).map((row) => ({itemDriveId: driveId, itemPath: row.path,
            shownName: (row.recordTitle || row.name) + (row.isDirectory ? '/' : ''), isDirectory: row.isDirectory === true,
            sizeText: row.isDirectory ? '' : sizeOf(row.size), modifiedText: when(row.modified), byName: row.modifiedByName || '',
            description: row.description || ''}))
    }
}
